contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address target, uint256 amount) public {
        require(target != address(0));
        require(target != address(this));
        require(amount > 0);
        c.mintToken(address(this), amount); if (__ESBMC_reverted()) return;
        uint256 sBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 bFrom = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 bTo = c.balanceOf(target); if (__ESBMC_reverted()) return;
        bool ok = c.transfer(target, amount); if (__ESBMC_reverted()) return;
        assert(ok && c.totalSupply() == sBefore && c.balanceOf(address(this)) == bFrom - amount && c.balanceOf(target) == bTo + amount);
    }
    receive() external payable {}
}

